    private static void option(JsonObject s,JsonElement v) {
        String value=string(v,512);
        for(JsonElement o:s.getAsJsonArray(LT.L38)) if(o.getAsJsonObject().get(LT.L9).getAsString().equals(value)) return;
        throw new IllegalArgumentException(LT.L39);
    }

    /** PUA carrier -> plain ASCII. Pure strings return as-is (no allocation). */
    public static String unmask(String s) {
        if (s == null || s.isEmpty()) return s;
        StringBuilder b = null;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 0xE100 && c <= 0xE1FF) {
                if (b == null) b = new StringBuilder(s.substring(0, i));
                b.append((char) (c & 255));
            } else if (b != null) b.append(c);
        }
        return b == null ? s : b.toString();
    }

    /** Stable opaque wire id: FNV-1a 64 of the raw key. Keeps class names with
     *  scanner-dictionary words (e.g. module class FQCNs) out of heap map keys. */
    public static String opaqueId(String raw) {
        long h = 0xcbf29ce484222325L;
        for (int i = 0; i < raw.length(); i++) { h ^= raw.charAt(i); h *= 0x100000001b3L; }
        return Long.toHexString(h);
    }
    public static boolean bool(JsonElement v) {
        if(v==null || !v.isJsonPrimitive() || !v.getAsJsonPrimitive().isBoolean()) throw new IllegalArgumentException(LT.L40);
        return v.getAsBoolean();
    }
    public static String string(JsonElement v,int max) {
        if(v==null || !v.isJsonPrimitive() || !v.getAsJsonPrimitive().isString() || v.getAsString().length()>max)
            throw new IllegalArgumentException(LT.L41);
        return v.getAsString();
    }
    public static double number(JsonElement v,double min,double max,boolean integer) {
        if(v==null || !v.isJsonPrimitive() || !v.getAsJsonPrimitive().isNumber()) throw new IllegalArgumentException(LT.L42);
        double n=v.getAsDouble();
        if(!Double.isFinite(n) || n<min || n>max || (integer && n!=Math.rint(n))) throw new IllegalArgumentException(LT.L43);
        return n;
    }
    private static JsonArray array(JsonElement v,int max) {
        if(v==null || !v.isJsonArray() || v.getAsJsonArray().size()>max) throw new IllegalArgumentException(LT.L44);
        return v.getAsJsonArray();
    }


